#!/usr/bin/env bash
# Local production rehearsal: the production compose file, images built from this tree,
# APP_ENV=production with AUTH_MODE=supabase (the local Supabase CLI stack), and the real
# deploy.sh, migrations, Caddy, backup and restore. See deploy/rehearsal.md.
#
#   deploy/rehearsal/rehearsal.sh up      # build, deploy, start
#   deploy/rehearsal/rehearsal.sh smoke   # the end-to-end checks
#   deploy/rehearsal/rehearsal.sh down    # remove containers, volumes and generated files
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
root="$(cd "$here/../.." && pwd)"
export COMPOSE_FILES="compose.prod.yml rehearsal/compose.rehearsal.yml"
export ENV_FILE="rehearsal/.env.rehearsal"
export COMPOSE_PROJECT="inmo24x7-rehearsal"
export IMAGE_PREFIX="inmo24x7-rehearsal"
env_path="$here/.env.rehearsal"
key_path="$here/backup.agekey"

# shellcheck source=SCRIPTDIR/../lib.sh
source "$here/../lib.sh"

fail() {
	echo "rehearsal: $*" >&2
	exit 1
}

supabase_env() {
	(cd "$root" && npx --yes supabase@2 status -o env 2>/dev/null) || true
}

commit_sha() {
	local sha
	sha="$(git -C "$root" rev-parse HEAD)"
	if [[ -n "$(git -C "$root" status --porcelain)" ]]; then
		sha="${sha}-dirty"
	fi
	echo "$sha"
}

write_env() {
	local status api_url anon_key jwt_secret jwks_keys recipient
	status="$(supabase_env)"
	api_url="$(sed -n 's/^API_URL="\(.*\)"$/\1/p' <<<"$status")"
	anon_key="$(sed -n 's/^ANON_KEY="\(.*\)"$/\1/p' <<<"$status")"
	jwt_secret="$(sed -n 's/^JWT_SECRET="\(.*\)"$/\1/p' <<<"$status")"
	[[ -n "$api_url" && -n "$anon_key" ]] || fail "the local Supabase stack is not running.
Start it with 'npx supabase start' (repository root). The rehearsal never uses AUTH_MODE=dev."
	local server_url="${api_url/127.0.0.1/host.docker.internal}"
	server_url="${server_url/localhost/host.docker.internal}"
	# Asymmetric keys when the CLI publishes them, the shared secret otherwise.
	jwks_keys="$(curl -fsS "$api_url/auth/v1/.well-known/jwks.json" 2>/dev/null | grep -c '"kid"' || true)"

	docker build -q -t inmo24x7-backup:rehearsal "$DEPLOY_DIR/backup" >/dev/null
	if [[ ! -f "$key_path" ]]; then
		docker run --rm --entrypoint age-keygen inmo24x7-backup:rehearsal >"$key_path" 2>/dev/null
		chmod 600 "$key_path"
	fi
	recipient="$(sed -n 's/^# public key: //p' "$key_path")"

	umask 077
	cat >"$env_path" <<ENV
# Generated by rehearsal.sh from 'supabase status'. Throwaway values; deleted by 'down'.
IMAGE_PREFIX=$IMAGE_PREFIX
BACKUP_IMAGE=inmo24x7-backup:rehearsal
APP_DOMAIN=app.localhost
ADMIN_DOMAIN=admin.localhost
API_DOMAIN=api.localhost
ACME_EMAIL=rehearsal@localhost
CADDY_GLOBAL_OPTIONS=local_certs
APP_ENV=production
REHEARSAL=true
DATABASE_URL=postgresql+psycopg://postgres:rehearsal@db:5432/postgres
API_DB_POOL_SIZE=5
API_DB_MAX_OVERFLOW=2
WORKER_DB_POOL_SIZE=5
WORKER_CONCURRENCY=4
CORS_ORIGINS=https://app.localhost,https://admin.localhost
PANEL_URL=https://app.localhost
SUPPORT_EMAIL=soporte@rehearsal.localhost
AUTH_MODE=supabase
SUPABASE_URL=$api_url
SUPABASE_SERVER_URL=$server_url
SUPABASE_ANON_KEY=$anon_key
$(if ((jwks_keys > 0)); then
		echo "SUPABASE_JWKS_URL=$server_url/auth/v1/.well-known/jwks.json"
	else
		echo "SUPABASE_JWT_SECRET=$jwt_secret"
	fi)
LLM_MODEL=
LANGSMITH_TRACING=false
WHATSAPP_SENDER=log
META_APP_ID=rehearsal-app
META_APP_SECRET=$(openssl rand -hex 24)
META_EMBEDDED_SIGNUP_CONFIG_ID=rehearsal-config
WHATSAPP_VERIFY_TOKEN=$(openssl rand -hex 16)
TOKEN_ENCRYPTION_KEY=$(openssl rand -base64 32)
INBOUND_DEBOUNCE_SECONDS=1
SMTP_HOST=mailpit
SMTP_PORT=1025
SMTP_STARTTLS=false
EMAIL_FROM=inmo24x7 <avisos@rehearsal.localhost>
BACKUP_AGE_RECIPIENT=$recipient
BACKUP_REMOTE=:local:/backups
BACKUP_KEEP_DAILY=14
BACKUP_KEEP_WEEKLY=8
ENV
	# Read by the panel builds below.
	echo "$api_url" >"$here/.supabase_url"
	echo "$anon_key" >"$here/.supabase_anon_key"
}

build_images() {
	local sha="$1" supabase_url anon_key
	supabase_url="$(cat "$here/.supabase_url")"
	anon_key="$(cat "$here/.supabase_anon_key")"
	say "Building images for this machine, tagged sha-$sha"
	docker build -q -f "$root/apps/inmo24x7/api/Dockerfile" \
		--build-arg APP_VERSION=rehearsal --build-arg GIT_COMMIT="$sha" \
		--build-arg BUILD_DATE="$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
		-t "$IMAGE_PREFIX/inmo24x7-api:sha-$sha" "$root" >/dev/null
	local app
	for app in web backoffice; do
		docker build -q -f "$root/apps/inmo24x7/$app/Dockerfile" \
			--build-arg VITE_AUTH_MODE=supabase \
			--build-arg VITE_API_URL=https://api.localhost \
			--build-arg VITE_SUPABASE_URL="$supabase_url" \
			--build-arg VITE_SUPABASE_ANON_KEY="$anon_key" \
			--build-arg VITE_PANEL_URL=https://app.localhost \
			--build-arg VITE_META_APP_ID=rehearsal-app \
			--build-arg VITE_META_EMBEDDED_SIGNUP_CONFIG_ID=rehearsal-config \
			-t "$IMAGE_PREFIX/inmo24x7-$app:sha-$sha" "$root" >/dev/null
	done
}

up() {
	command -v docker >/dev/null || fail "Docker is required."
	write_env
	local sha
	sha="$(commit_sha)"
	build_images "$sha"
	say "Starting the stand-ins for Supabase's database and the SMTP provider"
	IMAGE_TAG="sha-$sha" compose up -d --wait db mailpit
	"$DEPLOY_DIR/deploy.sh" "$sha" --local-images
	say "Up. Panel https://app.localhost  Backoffice https://admin.localhost  Mail http://127.0.0.1:58025"
}

down() {
	compose --profile tools down --volumes --remove-orphans || true
	rm -f "$env_path" "$key_path" "$here/.supabase_url" "$here/.supabase_anon_key"
	rm -rf "$DEPLOY_DIR/state-rehearsal"
	say "Rehearsal removed (images stay; 'docker image prune' clears them)."
}

case "${1:-}" in
up) up ;;
smoke) exec "$here/smoke.sh" ;;
down) down ;;
*)
	echo "usage: rehearsal.sh up|smoke|down" >&2
	exit 2
	;;
esac
